import { useCallback } from 'react';

import { usePageFilterManagement } from 'hooks';
import { FilterValue } from 'models/Filters';

import { COMMERCIAL_RESULTS_PAGE_NAME } from '../../constants';

export const useCommercialResultsQuickFilterApply = () => {
  const { applyDirect } = usePageFilterManagement(COMMERCIAL_RESULTS_PAGE_NAME);

  return useCallback(
    (key: string, value: FilterValue) => {
      if (key === 'brands') {
        applyDirect({
          brands: value,
          sub_brands: 'All',
          sku: 'All',
        });
        return;
      }

      applyDirect({ [key]: value });
    },
    [applyDirect],
  );
};
